def finding(item, ordinal, refs):
    fid, name, primary = item
    low = name.lower()
    kinds = [primary, KINDS[(ordinal + 9) % len(KINDS)], KINDS[(ordinal + 18) % len(KINDS)]]
    return {"id": fid, "name": name,
        "description": f"Records {low} as source-qualified Regulatory Filing / Disclosure context while reporting entity, regulator, obligation, law, domain fact, permit, application, case, decision, assessment, sanction, payment and records masters remain independently identifiable.",
        "source_refs": refs,
        "questions": [
            {"id": f"{fid}-q01", "text": f"Which stable filing, revision, reporting entity, obligation, reference period, jurisdiction, form, schema and external-master identities establish {low}?", "kind": kinds[0], "answer_data": ["filing, revision, reporting entity, registration, LEI, obligation, period, jurisdiction and master-system identifiers", "periodic, event-driven, initial, amended, corrected, restated, replacement, withdrawal and nil classes", "draft, prepared, reviewed, approved, signed, submitted, received, valid, accepted-for-processing, published, superseded and closed states"]},
            {"id": f"{fid}-q02", "text": f"Who prepares, reviews, approves, signs, transmits, publishes, receives, validates, investigates or may rely on {low}, for which purpose and under what authority?", "kind": kinds[1], "answer_data": ["reporting entity, preparer, reviewer, approver, signer, representative, transmitter, publisher, repository, regulator and auditor", "law, reporting obligation, form instruction, filing mandate, delegation, signature, policy, jurisdiction and segregation of duties", "purpose, scope, responsibility, deadline, exception, confidentiality, accountability and contestability"]},
            {"id": f"{fid}-q03", "text": f"Which concept, value, unit, rule version, source, evidence, method, event time, knowledge time, uncertainty, successor lineage and projection loss qualify {low}?", "kind": kinds[2], "answer_data": ["reported fact, narrative, metric, context, dimension, unit, currency, precision, nil reason and confidentiality class", "form, schema, taxonomy, code set, validation rule, source evidence, control, signature and regulator response", "reference, due, preparation, approval, signature, submission, receipt, publication, observation, ingestion and knowledge times, predecessor, successor, retention, access and mapping loss"]}],
        "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed regulatory filing or disclosure data for {low}, qualified by source, authority, rule, version, period, time, uncertainty, confidentiality and provenance.", "value_kind": "object", "cardinality": "1", "required": True, "source_refs": refs}],
        "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or versioned evidence for {low} with filing and revision identity, digest, source, profile version, event and knowledge times, access marking and successor lineage.", "media_or_form": ["application/yaml", "application/json", "application/xml", "text/csv", "text/markdown", "text/html"], "serial": True, "identity_strategy": "Prefer the authoritative reporting-entity, regulator, filing, repository, acknowledgement or records identifier; otherwise use a governed IRI, then a Dimension UUID or ULID.", "source_refs": refs}],
        "inline_only_rationale": None}


def structure():
    bundles, ordinal = [], 0
    for bid, bname, rationale, layers in ROWS:
        built, bundle_refs = [], []
        for lid, lname, refs, items in layers:
            fs = []
            for item in items:
                ordinal += 1
                fs.append(finding(item, ordinal, refs))
            built.append({"id": lid, "name": lname, "description": f"Groups governed {lname.lower()} for Regulatory Filing / Disclosure.", "source_refs": refs, "findings": fs})
            bundle_refs.extend(refs)
        bundles.append({"id": bid, "name": bname, "description": rationale, "rationale": rationale, "source_refs": list(dict.fromkeys(bundle_refs)), "layers": built})
    return {"bundles": bundles}


